import osimport jsonimport loggingimport pymongofrom flask import Flask, request, render_template, jsonify, redirect, url_forfrom dotenv import load_dotenvlogging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')load_dotenv()MONGO_URI = os.getenv('MONGO_URI')if not MONGO_URI:    logging.error("MONGO_URI not found in environment variables!")    db = Noneelse:    try:        client = pymongo.MongoClient(MONGO_URI)        db = client.test        logging.info("MongoDB connected successfully.")    except Exception as e:        logging.error(f"Failed to connect to MongoDB: {e}")        db = Noneapp = Flask(__name__)def validate_input(data):    name = data.get("name", "").strip()    email = data.get("email", "").strip()    if not name:        return False, "Name is required."    if not email or "@" not in email or "." not in email:        return False, "A valid email address is required."    return True, {"name": name, "email": email}@app.route('/')def home():    return render_template('form.html')@app.route('/submit', methods=['POST'])def submit():    if db is None:        logging.error("Database connection unavailable on form submission.")        return "Database connection error", 500    form_data = dict(request.form)    is_valid, clean_data = validate_input(form_data)    if not is_valid:        logging.warning(f"Validation failed: {clean_data}")        return render_template('form.html', error=clean_data)    try:        db.submissions.insert_one(clean_data)        logging.info(f"Successfully inserted submission for {clean_data['email']}")        return redirect(url_for('success'))    except pymongo.errors.PyMongoError as e:        logging.error(f"Database write failed: {e}")        return "Error saving data", 500@app.route('/success')def success():    return render_template('success.html')@app.route('/api')def get_api():    try:        with open('data.json', 'r') as f:            data = json.load(f)        return jsonify(data)    except FileNotFoundError:        logging.error("data.json file missing.")        return jsonify({"error": "File not found"}), 404@app.route('/health')def health():    return jsonify({"status": "UP" if db is not None else "DOWN"}), 200if __name__ == '__main__':    is_debug = os.getenv("FLASK_ENV") == "development"    app.run(debug=is_debug)